"""Original diagrams: disk continuity, constrained access and artifact promotion."""


def field(name, before, after, why):
    return dict(name=name,before=before,after=after,why=why)


def step(title, explanation, actor, focus, active, states, *fields):
    return dict(title=title,explanation=explanation,actor=actor,
                focus=focus.split(),active=active.split(),states=states,
                fields=list(fields),bands=[dict(label=f['name'],value=f['after'],detail=f['why']) for f in fields])


def diagram(identifier,chapter,title,intro,assumptions,nodes,edges,steps,takeaway,sources):
    initial = {
        'pc-world-continuity':dict(guest='Установленная ОС',disk='Диск текущей VM',point='Точка ещё не создана',other='Ожидает переноса'),
        'pc-bastion-path':dict(client='Клиент управления',bastion='Ожидает соединения',target='Внутренний SSH-сервер',console='Резервный канал владельца'),
        'pc-release-promotion':dict(artifact='Подготовленный кандидат',blue='v1 обслуживает',green='v2 ещё не запущена',entry='Маршрут на Blue'),
    }[identifier]
    for current in steps:
        initial.update(current['states'])
        current['states']=dict(initial)
    return dict(id=identifier,volume='practicum',chapter=chapter,anchor=chapter,
                title=title,intro=intro,assumptions=assumptions,
                nodes=[dict(id=i,label=label,sub=sub) for i,label,sub in nodes],
                edges=[dict(id=i,**{'from':a,'to':b},label=label) for i,a,b,label in edges],
                steps=steps,takeaway=takeaway,sources=sources)


